package dev.myjarvis.core;

import jakarta.servlet.http.Cookie;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

/** Profile routes, including the real API-controller GET /me delegation. */
class OwnerProfileHttpTest {
    MockMvc http;OwnerProfileService profiles;AuthService auth;AuthService.Session session;Cookie cookie;UUID owner,key;
    @BeforeEach void setup(){owner=UUID.randomUUID();key=UUID.fromString("abcdefab-cdef-4abc-8abc-abcdefabcdef");session=new AuthService.Session("synthetic-profile-session",owner,Instant.now(),1);cookie=new Cookie(WebSecurity.COOKIE,"synthetic-profile-token");auth=mock(AuthService.class);profiles=mock(OwnerProfileService.class);when(auth.find("synthetic-profile-token")).thenReturn(session);when(auth.csrf(session,"synthetic-csrf")).thenReturn(true);http=MockMvcBuilders.standaloneSetup(new OwnerProfileController(profiles),new ApiController(auth,mock(WorkflowService.class),mock(MockWorker.class),mock(LocalInferenceService.class),profiles)).setControllerAdvice(new ApiErrors()).addFilters(new WebSecurity(auth,"https://localhost:8443",false)).build();}
    @Test void explicitPatchPassesServerSessionAndExactBody() throws Exception{when(profiles.patch(eq(session),eq(key),any())).thenReturn(Map.of("profile",Map.of("version",2),"mutation",Map.of("status","COMMITTED")));var response=http.perform(patch("/api/v1/me").cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","synthetic-csrf").header("Idempotency-Key",key.toString()).contentType("application/json").content("{\"expected_version\":1,\"locale\":\"en-US\"}")).andReturn().getResponse();assertEquals(200,response.getStatus());assertEquals("no-store",response.getHeader("Cache-Control"));verify(profiles).patch(eq(session),eq(key),argThat(b->b.size()==2&&b.path("expected_version").asLong()==1&&b.path("locale").asText().equals("en-US")));}
    @Test void authenticationOriginAndCsrfRejectBeforeSettings() throws Exception{assertEquals(401,http.perform(get("/api/v1/profile-options")).andReturn().getResponse().getStatus());assertEquals(403,http.perform(patch("/api/v1/me").cookie(cookie).contentType("application/json").content("{}")).andReturn().getResponse().getStatus());assertEquals(403,http.perform(patch("/api/v1/me").cookie(cookie).header("Origin","https://localhost:8443").contentType("application/json").content("{}")).andReturn().getResponse().getStatus());verifyNoInteractions(profiles);}
    @Test void strictQueryAndIdempotencyHeaderValidation() throws Exception{for(String value:List.of("","1-1-1-1-1",key.toString().toUpperCase(Locale.ROOT))){var request=patch("/api/v1/me").cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","synthetic-csrf").contentType("application/json").content("{}");if(!value.isEmpty())request.header("Idempotency-Key",value);assertEquals(400,http.perform(request).andReturn().getResponse().getStatus());}assertEquals(400,http.perform(patch("/api/v1/me").cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","synthetic-csrf").header("Idempotency-Key",key.toString(),key.toString()).contentType("application/json").content("{}")).andReturn().getResponse().getStatus());for(String path:List.of("/api/v1/profile-options?owner_id="+owner,"/api/v1/profile-mutations/"+key+"?value=private","/api/v1/profile-mutations/1-1-1-1-1"))assertEquals(400,http.perform(get(path).cookie(cookie)).andReturn().getResponse().getStatus());verifyNoInteractions(profiles);}
    @Test void receiptReadNeverReplaysPatch() throws Exception{Map<String,Object> result=new LinkedHashMap<>();result.put("status","NOT_OBSERVED");result.put("owner_id",null);result.put("version",null);result.put("updated_fields",null);when(profiles.reconcile(session,key)).thenReturn(result);var response=http.perform(get("/api/v1/profile-mutations/"+key).cookie(cookie)).andReturn().getResponse();assertEquals(200,response.getStatus());assertEquals("NOT_OBSERVED",Json.parse(response.getContentAsByteArray()).path("data").path("status").asText());verify(profiles).reconcile(session,key);verifyNoMoreInteractions(profiles);}
    @Test void conflictReturnsVersionWithoutProfileValues() throws Exception{when(profiles.patch(eq(session),eq(key),any())).thenThrow(new OwnerProfileService.ProfileConflict(3));var response=http.perform(patch("/api/v1/me").cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","synthetic-csrf").header("Idempotency-Key",key.toString()).contentType("application/json").content("{\"expected_version\":1,\"display_name\":\"Synthetic Private\"}")).andReturn().getResponse();assertEquals(409,response.getStatus());var error=Json.parse(response.getContentAsByteArray()).path("error");assertEquals("PRECONDITION_CHANGED",error.path("code").asText());assertEquals(1,error.path("details").size());assertEquals(3,error.path("details").path("current_version").asLong());assertFalse(response.getContentAsString().contains("Synthetic Private"));}
    @Test void actualMeControllerDelegatesReadAndRejectsUnknownQuery() throws Exception{
        when(profiles.get(session)).thenReturn(Map.of("id",owner,"version",2,"timezone","Asia/Seoul"));
        var response=http.perform(get("/api/v1/me").cookie(cookie)).andReturn().getResponse();assertEquals(200,response.getStatus());assertEquals("no-store",response.getHeader("Cache-Control"));assertEquals("Asia/Seoul",Json.parse(response.getContentAsByteArray()).path("data").path("timezone").asText());verify(profiles).get(session);
        assertEquals(400,http.perform(get("/api/v1/me?owner_id="+owner).cookie(cookie)).andReturn().getResponse().getStatus());assertEquals(400,http.perform(patch("/api/v1/me?owner_id="+owner).cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","synthetic-csrf").header("Idempotency-Key",key.toString()).contentType("application/json").content("{\"expected_version\":2,\"locale\":\"en-US\"}")).andReturn().getResponse().getStatus());assertEquals(401,http.perform(get("/api/v1/me")).andReturn().getResponse().getStatus());verifyNoMoreInteractions(profiles);
    }

}
